    @staticmethod
    def _flat_comment_text(path) -> str:
        """A YAML header's comment prose, markers off and whitespace flat."""
        return " ".join(" ".join(
            line.lstrip().lstrip("#").strip()
            for line in path.read_text(encoding="utf-8").splitlines()).split())


